#!/bin/zsh

# Stow files
PWD="$(pwd)"
cd $HOME/.dotfiles/config
stow -R -t ~ .
cd $PWD

# Install Brew
if [ -z "$(command -v brew)" ]; then
    /bin/bash -c "$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)"

    # Remove bash config files generated by the install script
    rm "$HOME/.bash*"

    if [ "$(uname -s)" = "Linux" ]; then
        eval "$(/home/linuxbrew/.linuxbrew/bin/brew shellenv)"
    fi
fi

# Install brew packages
BREWFILE_PATH="$HOME/Brewfile"

if [ -f "$BREWFILE_PATH" ]; then
    brew bundle check --file $BREWFILE_PATH || brew bundle install --file $BREWFILE_PATH --upgrade
    brew bundle cleanup --force --file $BREWFILE_PATH
fi

source "$HOME/.zshrc"
